"""Receiver reconstruction of actual scalar samples generated by the source.

This is a transparent, *new* application encoding contract, NOT an existing
codec in the submitted manuscript. The selected packet length provides
padding; the first 16 bits hold a signed fixed-point scalar value (Q8.8).
Decode only if complete application packet is delivered; otherwise sink
holds last value. The entire node state/PHY/failure path comes unchanged
from the original simulator. Event labels are scoring data, not inputs.

This reveals whether *packet size alone* changes the usefulness of one
scalar report: it cannot improve quantization after 16 bits are delivered.
"""
import math
import numpy as np

class ScalarSourceReceiver:
    def __init__(self, n, threshold=0.5):
        self.last=np.zeros(int(n),dtype=float)
        self.sse=0.
        self.truth_sse=0.
        self.records=0
        self.received=0
        self.tp=self.fp=self.fn=0
        self.threshold=threshold

    def record(self, node, round_id, sample, truth, bits, delivered):
        node=int(node)
        sample=float(sample)
        if int(bits)<16:
            raise ValueError("Packet too short for signed scalar source sample")
        # Saturating symmetric fixed point, 1/256 quantization.
        if delivered:
            code=int(np.clip(np.rint(sample*256),-32768,32767))
            self.last[node]=code/256.0
            self.received+=1
        actual=float(self.last[node])
        self.sse+=(sample-actual)**2
        self.truth_sse+=sample*sample
        predicted=actual>=self.threshold
        self.tp+=int(predicted and bool(truth))
        self.fp+=int(predicted and not bool(truth))
        self.fn+=int(not predicted and bool(truth))
        self.records+=1

    def results(self):
        precision=self.tp/(self.tp+self.fp) if self.tp+self.fp else 0.
        recall=self.tp/(self.tp+self.fn) if self.tp+self.fn else 0.
        f1=2*precision*recall/(precision+recall) if precision+recall else 0.
        return dict(rmse=math.sqrt(self.sse/self.records),
                    zero_rmse=math.sqrt(self.truth_sse/self.records),
                    event_f1=f1,precision=precision,recall=recall,
                    reports=self.records,received=self.received,
                    tp=self.tp,fp=self.fp,fn=self.fn)
